// ===========================================================================
// BUILT-IN HARDWARE ACCELERATED KERNELS
// ===========================================================================
static inline int8_t shannon_clamp_int8(int32_t val) {
    if (val > 127) return 127;
    if (val < -128) return -128;
    return (int8_t)val;
}

static void shannon_dense_int8(const int8_t* in, const int8_t* w, const int32_t* bias, int8_t* out, int in_feat, int out_feat) {
    for (int o = 0; o < out_feat; o++) {
        int32_t acc = bias ? bias[o] : 0;
        const int8_t* w_row = &w[o * in_feat];
        for (int i = 0; i < in_feat; i++) {
            acc += (int32_t)in[i] * (int32_t)w_row[i];
        }
        // Scale down accumulator and clamp to INT8 range
        acc = acc >> 7;
        out[o] = shannon_clamp_int8(acc);
    }
}

static void shannon_relu_int8(int8_t* data, int size) {
    for (int i = 0; i < size; i++) {
        if (data[i] < 0) data[i] = 0;
    }
}

static void shannon_maxpool_int8(const int8_t* in, int8_t* out, int in_len, int stride) {
    int out_idx = 0;
    for (int i = 0; i < in_len; i += stride) {
        int8_t max_val = in[i];
        for (int k = 1; k < stride && (i + k) < in_len; k++) {
            if (in[i + k] > max_val) max_val = in[i + k];
        }
        out[out_idx++] = max_val;
    }
}

// ===========================================================================
// MAIN INFERENCE ENTRYPOINT
// ===========================================================================
static inline int shannon_run_inference(const int8_t* input_data, int8_t* output_data) {
    // Layer 1: enc_dense1 (Dense)
    int8_t* in_ptr_0 = (int8_t*)input_data;
    int8_t* out_ptr_0 = (int8_t*)&shannon_tensor_arena[0];
    shannon_dense_int8(in_ptr_0, shannon_enc_dense1_weights, shannon_enc_dense1_bias, out_ptr_0, 64, 32);

    // Layer 2: enc_bottleneck (Dense)
    int8_t* in_ptr_1 = (int8_t*)&shannon_tensor_arena[0];
    int8_t* out_ptr_1 = (int8_t*)&shannon_tensor_arena[32];
    shannon_dense_int8(in_ptr_1, shannon_enc_bottleneck_weights, shannon_enc_bottleneck_bias, out_ptr_1, 32, 8);

    // Layer 3: dec_dense1 (Dense)
    int8_t* in_ptr_2 = (int8_t*)&shannon_tensor_arena[32];
    int8_t* out_ptr_2 = (int8_t*)&shannon_tensor_arena[0];
    shannon_dense_int8(in_ptr_2, shannon_dec_dense1_weights, shannon_dec_dense1_bias, out_ptr_2, 8, 32);

    // Layer 4: dec_reconstruction (Dense)
    int8_t* in_ptr_3 = (int8_t*)&shannon_tensor_arena[0];
    int8_t* out_ptr_3 = output_data;
    shannon_dense_int8(in_ptr_3, shannon_dec_reconstruction_weights, shannon_dec_reconstruction_bias, out_ptr_3, 32, 64);

    return 0; // Success
}

